Q: How to model data to Rust type A: <p>This is really close to what I went with. I think you need to have a function like data state to restrict the access of the data with your own logic because types are not enough to represent everything by themselves.</p>
<p>This is what I went with</p>
<pre class="lang-rs prettyprint-override"><code>pub struct ApiError {
    kind: ApiErrorKind,
    num_cycles_missed: u32, 
}

pub struct ApiResponse&lt;T&gt; {
    data: Option&lt;T&gt;,
    api_error: Option&lt;ApiError&gt;,
}

impl&lt;T&gt; ApiResponse&lt;T&gt; {
    pub fn get_data(&amp;self, num_stale_accepted: u32) -&gt; Result&lt;&amp;T, &amp;ApiErrorKind&gt; {
        match (self.data.as_ref(), self.api_error.as_ref()) {
            (None, None) =&gt; unreachable!(
                &quot;ApiResponse::get_data() called before update_with(): data and error cannot both be None&quot;
            ),
            (None, Some(e)) =&gt; Err(&amp;e.kind),
            (Some(v), None) =&gt; Ok(&amp;v),
            (Some(v), Some(e)) if e.num_cycles_missed &lt;= num_stale_accepted =&gt; Ok(&amp;v),
            (Some(_), Some(e)) =&gt; Err(&amp;e.kind),
        }
    }

    // This will be used to show metadata about errors if they exist
    pub fn get_error(&amp;self) -&gt; &amp;Option&lt;ApiError&gt; {
        &amp;self.api_error
    }

    // This will be used when a new response is fetched from the api
    pub fn update_with(&amp;mut self, response: Result&lt;T, ApiErrorKind&gt;) {
        match response {
            Ok(data) =&gt; {
                self.data = Some(data);
                self.api_error = None;
            }

            Err(e) =&gt; match self.api_error.as_mut() {
                Some(api_error) =&gt; {
                    api_error.kind = e;
                    api_error.num_cycles_missed += 1;
                }
                None =&gt; {
                    self.api_error = Some(ApiError {
                        kind: e,
                        num_cycles_missed: 1,
                    })
                }
            },
        }
    }
}
</code></pre>

